diff --git a/counting/aggregation.cpp b/counting/aggregation.cpp
index 6dc7d8c..4d0defc 100644
--- a/counting/aggregation.cpp
+++ b/counting/aggregation.cpp
@@ -1 +1,1840 @@
 #include "aggregation.h"
+
+#include <algorithm>
+#include <cmath>
+#include <cstdio>
+#include <cstdlib>
+#include <cstring>
+#include <functional>
+#include <new>
+#include <map>
+#include <unordered_map>
+#ifdef __linux__
+#include <sys/mman.h>
+#endif
+#if defined(__AVX512BW__)
+#include <immintrin.h>
+#endif
+
+namespace localcount {
+
+typedef int64_t i64;
+typedef std::vector<i64> Vec;
+
+// ---------------------------------------------------------------------------------------
+// Rooted shapes: connected graphs on at most five vertices with a distinguished root.
+// ---------------------------------------------------------------------------------------
+
+struct Shape {
+    int q = 0;
+    uint8_t adj[5] = {0, 0, 0, 0, 0};
+    int root = 0;
+};
+
+inline int popc(unsigned x) { return __builtin_popcount(x); }
+
+// Minimum edge code over all relabelings that send the root to 0.
+uint32_t shapeKey(const Shape &s) {
+    int others[4], k = 0;
+    for (int i = 0; i < s.q; ++i)
+        if (i != s.root) others[k++] = i;
+    int perm[4] = {0, 1, 2, 3};
+    uint32_t best = UINT32_MAX;
+    do {
+        int lab[5];
+        lab[s.root] = 0;
+        for (int i = 0; i < k; ++i) lab[others[i]] = perm[i] + 1;
+        uint32_t code = 0;
+        for (int a = 0; a < s.q; ++a)
+            for (int b = a + 1; b < s.q; ++b)
+                if (s.adj[a] >> b & 1) {
+                    int x = lab[a], y = lab[b];
+                    if (x > y) std::swap(x, y);
+                    code |= 1u << (x * 5 + y);
+                }
+        best = std::min(best, code);
+    } while (std::next_permutation(perm, perm + k));
+    return best | ((uint32_t)s.q << 25);
+}
+
+// Inner product of two int16 rows whose length is a multiple of 32; the caller guarantees
+// that the result fits in int32.
+inline int32_t dot16(const int16_t *a, const int16_t *b, size_t len) {
+#if defined(__AVX512BW__)
+    __m512i acc = _mm512_setzero_si512();
+    for (size_t i = 0; i < len; i += 32) {
+        __m512i x = _mm512_loadu_si512(a + i), y = _mm512_loadu_si512(b + i);
+#if defined(__AVX512VNNI__)
+        acc = _mm512_dpwssd_epi32(acc, x, y);
+#else
+        acc = _mm512_add_epi32(acc, _mm512_madd_epi16(x, y));
+#endif
+    }
+    return _mm512_reduce_add_epi32(acc);
+#else
+    int32_t s = 0;
+    for (size_t i = 0; i < len; ++i) s += (int32_t)a[i] * (int32_t)b[i];
+    return s;
+#endif
+}
+
+unsigned twoCore(const Shape &s) {
+    unsigned mask = (1u << s.q) - 1;
+    bool changed = true;
+    while (changed) {
+        changed = false;
+        for (int i = 0; i < s.q; ++i)
+            if ((mask >> i & 1) && popc(s.adj[i] & mask) <= 1) {
+                mask &= ~(1u << i);
+                changed = true;
+            }
+    }
+    return mask;
+}
+
+// Zero-initialized array for large tables. Anonymous mappings arrive zero-filled, so the pages
+// are not cleared twice; transparent huge pages are requested where available.
+template<class T>
+class BigArray {
+public:
+    BigArray() = default;
+    BigArray(const BigArray &) = delete;
+    BigArray &operator=(const BigArray &) = delete;
+    ~BigArray() { release(); }
+
+    void assign(size_t count) {
+        release();
+        size_t bytes = count * sizeof(T) + 64;
+#if defined(__linux__) && defined(MAP_ANONYMOUS)
+        void *p = mmap(nullptr, bytes, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
+        if (p != MAP_FAILED) {
+#ifdef MADV_HUGEPAGE
+            madvise(p, bytes, MADV_HUGEPAGE);
+#endif
+            ptr = static_cast<T *>(p);
+            mapped = bytes;
+            return;
+        }
+#endif
+        void *q = std::calloc(1, bytes);
+        if (!q) throw std::bad_alloc();
+        ptr = static_cast<T *>(q);
+    }
+
+    T *data() { return ptr; }
+    const T *data() const { return ptr; }
+
+private:
+    void release() {
+#if defined(__linux__) && defined(MAP_ANONYMOUS)
+        if (ptr && mapped) munmap(ptr, mapped);
+        else
+#endif
+            std::free(ptr);
+        ptr = nullptr;
+        mapped = 0;
+    }
+
+    T *ptr = nullptr;
+    size_t mapped = 0;
+};
+
+// Cores with a dedicated kernel. Cores on fewer than five vertices accept vertex weights
+// (from hanging trees); five-vertex cores never have hanging trees.
+enum CoreType { K3, C4, DIAMOND, K4, C5, BOWTIE, HOUSE, GEM, K23E, K5MP3, K5, NUM_CORES };
+
+struct CoreDef {
+    int k;
+    std::vector<std::pair<int, int>> edges;
+    std::vector<int> roots;     // supported root positions; others are reached by automorphism
+    bool weighted;
+};
+
+const CoreDef &coreDef(int t) {
+    static const CoreDef defs[NUM_CORES] = {
+            {3, {{0, 1}, {0, 2}, {1, 2}}, {0}, true},
+            {4, {{0, 1}, {1, 2}, {2, 3}, {0, 3}}, {0}, true},
+            // 0,1: the shared edge; 2,3: the tips
+            {4, {{0, 1}, {0, 2}, {0, 3}, {1, 2}, {1, 3}}, {0, 2}, true},
+            {4, {{0, 1}, {0, 2}, {0, 3}, {1, 2}, {1, 3}, {2, 3}}, {0}, true},
+            {5, {{0, 1}, {1, 2}, {2, 3}, {3, 4}, {0, 4}}, {0}, false},
+            // center 0, triangles (0,1,2) and (0,3,4)
+            {5, {{0, 1}, {0, 2}, {1, 2}, {0, 3}, {0, 4}, {3, 4}}, {0, 1}, false},
+            // roof 2, top 0 and 1, bottom 3 (below 0) and 4 (below 1)
+            {5, {{0, 1}, {0, 2}, {1, 2}, {0, 3}, {1, 4}, {3, 4}}, {2, 0, 3}, false},
+            // apex 0 over the path 3-1-2-4
+            {5, {{0, 1}, {0, 2}, {0, 3}, {0, 4}, {1, 2}, {1, 3}, {2, 4}}, {0, 1, 3}, false},
+            // K_{2,3} with parts {2,3} and {0,1,4}, plus the edge (0,1)
+            {5, {{0, 1}, {0, 2}, {0, 3}, {1, 2}, {1, 3}, {2, 4}, {3, 4}}, {4, 0, 2}, false},
+            // K4 on {0,1,2,3}, vertex 4 adjacent to 0 and 1
+            {5, {{0, 1}, {0, 2}, {0, 3}, {0, 4}, {1, 2}, {1, 3}, {1, 4}, {2, 3}}, {4, 2, 0}, false},
+            {5, {{0, 1}, {0, 2}, {0, 3}, {0, 4}, {1, 2}, {1, 3}, {1, 4}, {2, 3}, {2, 4}, {3, 4}}, {0}, false},
+    };
+    return defs[t];
+}
+
+// Finds a core kernel and an isomorphism phi (kernel label -> shape vertex) such that the
+// entry vertex lands on a supported kernel root.
+bool matchCore(const Shape &s, unsigned coreMask, int entry, int &type, int phi[5], int &kernelRoot) {
+    int cv[5], k = 0;
+    for (int i = 0; i < s.q; ++i)
+        if (coreMask >> i & 1) cv[k++] = i;
+    int edgeCount = 0;
+    for (int i = 0; i < k; ++i) edgeCount += popc(s.adj[cv[i]] & coreMask);
+    edgeCount /= 2;
+    for (int t = 0; t < NUM_CORES; ++t) {
+        const CoreDef &d = coreDef(t);
+        if (d.k != k || (int)d.edges.size() != edgeCount) continue;
+        uint8_t cadj[5] = {0, 0, 0, 0, 0};
+        for (const auto &e: d.edges) {
+            cadj[e.first] |= 1u << e.second;
+            cadj[e.second] |= 1u << e.first;
+        }
+        int perm[5] = {0, 1, 2, 3, 4};
+        do {
+            bool ok = true;
+            for (int i = 0; i < k && ok; ++i)
+                for (int j = 0; j < k; ++j)
+                    if (((cadj[i] >> j) & 1) != ((s.adj[cv[perm[i]]] >> cv[perm[j]]) & 1)) {
+                        ok = false;
+                        break;
+                    }
+            if (!ok) continue;
+            int r = -1;
+            for (int i = 0; i < k; ++i)
+                if (cv[perm[i]] == entry) r = i;
+            if (std::find(d.roots.begin(), d.roots.end(), r) == d.roots.end()) continue;
+            type = t;
+            kernelRoot = r;
+            for (int i = 0; i < k; ++i) phi[i] = cv[perm[i]];
+            return true;
+        } while (std::next_permutation(perm, perm + k));
+    }
+    return false;
+}
+
+} // namespace localcount
+
+using namespace localcount;
+
+// ---------------------------------------------------------------------------------------
+// Input / output
+// ---------------------------------------------------------------------------------------
+
+namespace {
+
+bool readAll(const std::string &path, std::vector<char> &buf) {
+    FILE *f = fopen(path.c_str(), "rb");
+    if (!f) return false;
+    buf.clear();
+    char chunk[1 << 16];
+    size_t r;
+    while ((r = fread(chunk, 1, sizeof(chunk), f)) > 0) buf.insert(buf.end(), chunk, chunk + r);
+    fclose(f);
+    buf.push_back('\0');
+    return true;
+}
+
+// Parses non-negative decimal integers; returns false at the end of input.
+inline bool nextUInt(const char *&p, uint64_t &value) {
+    while (*p && (*p < '0' || *p > '9')) {
+        if (*p == '-') return false;
+        ++p;
+    }
+    if (!*p) return false;
+    uint64_t v = 0;
+    while (*p >= '0' && *p <= '9') v = v * 10 + (uint64_t)(*p++ - '0');
+    value = v;
+    return true;
+}
+
+} // namespace
+
+bool readSmallQuery(const std::string &path, SmallQuery &q) {
+    q = SmallQuery();
+    std::vector<char> buf;
+    if (!readAll(path, buf)) return false;
+    const char *p = buf.data();
+    uint64_t n, m, a, b;
+    if (!nextUInt(p, n) || !nextUInt(p, m)) return false;
+    if (n > 16 || m > 256) return false;
+    q.numVertices = (int)n;
+    for (uint64_t i = 0; i < m; ++i) {
+        if (!nextUInt(p, a) || !nextUInt(p, b)) return false;
+        q.edges.emplace_back((int)a, (int)b);
+    }
+    if (!nextUInt(p, a)) return false;
+    q.orbitType = (int)a;
+    if (q.orbitType != 1 || !nextUInt(p, b)) return false;
+    q.orbit = (int)b;
+    q.parsed = true;
+    return true;
+}
+
+bool LocalGraph::load(const std::string &path) {
+    std::vector<char> buf;
+    if (!readAll(path, buf)) return false;
+    const char *p = buf.data();
+    uint64_t nn, mm;
+    if (!nextUInt(p, nn) || !nextUInt(p, mm)) return false;
+    if (nn >= (1ull << 31) || mm >= (1ull << 30)) return false;
+    n = (uint32_t)nn;
+    m = (uint32_t)mm;
+    std::vector<uint32_t> src(m), dst(m);
+    for (uint32_t i = 0; i < m; ++i) {
+        uint64_t a, b;
+        if (!nextUInt(p, a) || !nextUInt(p, b)) return false;
+        if (a >= n || b >= n || a == b) return false;
+        src[i] = (uint32_t)a;
+        dst[i] = (uint32_t)b;
+    }
+    offsets.assign(n + 1, 0);
+    for (uint32_t i = 0; i < m; ++i) {
+        ++offsets[src[i] + 1];
+        ++offsets[dst[i] + 1];
+    }
+    for (uint32_t v = 0; v < n; ++v) offsets[v + 1] += offsets[v];
+    nbrs.assign(2ull * m, 0);
+    std::vector<uint32_t> pos(offsets.begin(), offsets.end() - 1);
+    for (uint32_t i = 0; i < m; ++i) {
+        nbrs[pos[src[i]]++] = dst[i];
+        nbrs[pos[dst[i]]++] = src[i];
+    }
+    for (uint32_t v = 0; v < n; ++v) {
+        std::sort(nbrs.begin() + offsets[v], nbrs.begin() + offsets[v + 1]);
+        for (uint32_t k = offsets[v] + 1; k < offsets[v + 1]; ++k)
+            if (nbrs[k] == nbrs[k - 1]) return false;   // multi-edges are not simple graphs
+    }
+    return true;
+}
+
+void writeLocalCounts(const std::string &path, const std::vector<int64_t> &counts) {
+    std::vector<char> out;
+    out.resize(counts.size() * 21 + 16);
+    char *w = out.data();
+    for (int64_t c: counts) {
+        uint64_t u;
+        if (c < 0) {
+            *w++ = '-';
+            u = (uint64_t)(-(c + 1)) + 1;
+        }
+        else u = (uint64_t)c;
+        char tmp[24];
+        int len = 0;
+        do {
+            tmp[len++] = (char)('0' + u % 10);
+            u /= 10;
+        } while (u);
+        while (len) *w++ = tmp[--len];
+        *w++ = '\n';
+    }
+    FILE *f = fopen(path.c_str(), "wb");
+    if (!f) return;
+    fwrite(out.data(), 1, (size_t)(w - out.data()), f);
+    fclose(f);
+}
+
+// ---------------------------------------------------------------------------------------
+// Counting kernels
+// ---------------------------------------------------------------------------------------
+
+struct SharedCounter::Impl {
+    const LocalGraph &g;
+    const uint32_t n;
+    const uint32_t m;
+    const uint32_t *off;
+    const uint32_t *adj;
+    Vec ones;
+
+    // undirected edge ids
+    bool edgeReady = false;
+    std::vector<uint32_t> eid;          // directed slot -> undirected edge id
+    std::vector<uint32_t> revSlot;      // directed slot (u,v) -> slot of (v,u)
+    std::vector<uint32_t> elo, ehi;     // endpoints, elo < ehi
+    // degree orientation: out-neighbors have a higher (degree, id) rank
+    std::vector<uint32_t> ooff, oadj, oeid;
+    std::vector<int32_t> mark;
+
+    // triangle structures
+    bool triReady = false;
+    std::vector<uint32_t> T;            // triangles per undirected edge
+    std::vector<i64> t2;                // per vertex: twice the number of triangles
+    std::vector<uint32_t> cnOff;        // per undirected edge: common neighbors
+    std::vector<uint32_t> cnV;
+    std::vector<uint16_t> cnV16;        // narrow copy used when vertex ids fit
+
+    bool k4Ready = false;
+    std::vector<uint32_t> K4e;          // 4-cliques per undirected edge
+    Vec k4Opp;                          // per vertex: over its 4-cliques, T of the three edges avoiding it
+
+    // dense A^2 (common-neighbor counts, diagonal = degree), used when it fits comfortably
+    bool a2Ready = false, a2Dense = false;
+    size_t np = 0;
+    BigArray<int16_t> M;
+
+    bool a3Ready = false;
+    std::vector<i64> A3;                // 3-walks between the endpoints of each edge
+    Vec houseBottom;
+
+    bool k23R0Ready = false, k23R2Ready = false, k23R4Ready = false;
+    Vec k23Root0, k23Root2, k23Root4;
+
+    // kernel roots required by the prepared batch; without preparation everything counts as needed
+    bool prepared = false;
+    std::vector<std::pair<int, int>> neededCores;
+
+    bool needed(int type, int root) const {
+        if (!prepared) return true;
+        return std::find(neededCores.begin(), neededCores.end(), std::make_pair(type, root)) != neededCores.end();
+    }
+
+    std::unordered_map<uint32_t, Vec> shapeCache;
+
+    uint32_t maxDeg = 0;
+
+    explicit Impl(const LocalGraph &graph)
+            : g(graph), n(graph.n), m(graph.m), off(graph.offsets.data()), adj(graph.nbrs.data()) {
+        ones.assign(n, 1);
+        for (uint32_t v = 0; v < n; ++v) maxDeg = std::max(maxDeg, off[v + 1] - off[v]);
+    }
+
+    inline uint32_t deg(uint32_t v) const { return off[v + 1] - off[v]; }
+
+    void spmv(const Vec &h, Vec &out) const {
+        out.assign(n, 0);
+        for (uint32_t v = 0; v < n; ++v) {
+            i64 s = 0;
+            for (uint32_t k = off[v]; k < off[v + 1]; ++k) s += h[adj[k]];
+            out[v] = s;
+        }
+    }
+
+    void buildA2() {
+        if (a2Ready) return;
+        a2Ready = true;
+        double sumSq = 0;
+        for (uint32_t v = 0; v < n; ++v) sumSq += (double)deg(v) * deg(v);
+        // int16 entries; inner products of rows are bounded by sum of squared degrees
+        if (maxDeg >= 32768 || sumSq >= 2.0e9 || (double)n * n > 3.0e8) return;
+        np = ((size_t)n + 31) & ~(size_t)31;
+        M.assign(np * n);
+        buildEdges();
+        if (sumSq < 1.3 * (double)n * n) {
+            for (uint32_t v = 0; v < n; ++v) {
+                int16_t *row = M.data() + np * v;
+                for (uint32_t k = off[v]; k < off[v + 1]; ++k) {
+                    uint32_t x = adj[k];
+                    for (uint32_t k2 = off[x]; k2 < off[x + 1]; ++k2) ++row[adj[k2]];
+                }
+            }
+            a2Dense = true;
+            return;
+        }
+        // dense products: build the upper triangle (c >= v), where v sits at slot revSlot[k] of
+        // the sorted list N(x), then mirror it tile by tile
+        for (uint32_t v = 0; v < n; ++v) {
+            int16_t *row = M.data() + np * v;
+            for (uint32_t k = off[v]; k < off[v + 1]; ++k) {
+                uint32_t x = adj[k];
+                for (uint32_t k2 = revSlot[k]; k2 < off[x + 1]; ++k2) ++row[adj[k2]];
+            }
+        }
+        const uint32_t B = 64;
+        for (uint32_t i0 = 0; i0 < n; i0 += B)
+            for (uint32_t j0 = i0; j0 < n; j0 += B) {
+                const uint32_t ie = std::min(i0 + B, n), je = std::min(j0 + B, n);
+                for (uint32_t i = i0; i < ie; ++i) {
+                    const int16_t *src = M.data() + np * i;
+                    for (uint32_t j = std::max(j0, i + 1); j < je; ++j) M.data()[np * j + i] = src[j];
+                }
+            }
+        a2Dense = true;
+    }
+
+    void buildEdges() {
+        if (edgeReady) return;
+        edgeReady = true;
+        eid.assign(2ull * m, 0);
+        revSlot.assign(2ull * m, 0);
+        elo.assign(m, 0);
+        ehi.assign(m, 0);
+        uint32_t next = 0;
+        for (uint32_t u = 0; u < n; ++u)
+            for (uint32_t k = off[u]; k < off[u + 1]; ++k) {
+                uint32_t v = adj[k];
+                if (u < v) {
+                    eid[k] = next;
+                    elo[next] = u;
+                    ehi[next] = v;
+                    ++next;
+                }
+                else {
+                    const uint32_t *b = adj + off[v], *e = adj + off[v + 1];
+                    const uint32_t *it = std::lower_bound(b, e, u);
+                    uint32_t r = off[v] + (uint32_t)(it - b);
+                    eid[k] = eid[r];
+                    revSlot[k] = r;
+                    revSlot[r] = k;
+                }
+            }
+        std::vector<uint64_t> rank(n);
+        for (uint32_t v = 0; v < n; ++v) rank[v] = ((uint64_t)deg(v) << 32) | v;
+        ooff.assign(n + 1, 0);
+        for (uint32_t u = 0; u < n; ++u)
+            for (uint32_t k = off[u]; k < off[u + 1]; ++k)
+                if (rank[adj[k]] > rank[u]) ++ooff[u + 1];
+        for (uint32_t u = 0; u < n; ++u) ooff[u + 1] += ooff[u];
+        oadj.assign(ooff[n], 0);
+        oeid.assign(ooff[n], 0);
+        for (uint32_t u = 0; u < n; ++u) {
+            uint32_t p = ooff[u];
+            for (uint32_t k = off[u]; k < off[u + 1]; ++k)
+                if (rank[adj[k]] > rank[u]) {
+                    oadj[p] = adj[k];
+                    oeid[p] = eid[k];
+                    ++p;
+                }
+        }
+        mark.assign(n, -1);
+    }
+
+    struct Tri {
+        uint32_t x, y, z, exy, exz, eyz;
+    };
+    std::vector<Tri> tris;
+
+    // f(x, y, z, e_xy, e_xz, e_yz) once per triangle
+    template<class F>
+    void forTriangles(F f) {
+        buildTriangleList();
+        for (const Tri &t: tris) f(t.x, t.y, t.z, t.exy, t.exz, t.eyz);
+    }
+
+    bool triListReady = false;
+    bool k3PairWeighted = false;
+
+    // whether some kernel of the prepared batch iterates over individual triangles
+    bool triListNeeded() const {
+        if (!prepared || k3PairWeighted) return true;
+        for (const auto &c: neededCores) {
+            int t = c.first, r = c.second;
+            if (t == DIAMOND || t == GEM || t == K23E || (t == HOUSE && r == 2) || (t == K5MP3 && r == 4))
+                return true;
+        }
+        return false;
+    }
+
+    // per-edge triangle counts T and per-vertex sums t2
+    void buildTriangles() {
+        if (triReady) return;
+        if (triListNeeded()) {
+            buildTriangleList();
+            return;
+        }
+        if (needed(K4, 0) && !k4StatsNeeded() && !k4CountReady && !k4Ready) {
+            // the 4-clique count pass derives T from the same local bitsets
+            cliquePass(false, true, needed(K5, 0), true);
+            return;
+        }
+        enumerateTriangles(false);
+    }
+
+    void buildTriangleList() {
+        if (triListReady) return;
+        enumerateTriangles(true);
+    }
+
+    void finishTriangleCounts() {
+        triReady = true;
+        t2.assign(n, 0);
+        for (uint32_t v = 0; v < n; ++v)
+            for (uint32_t k = off[v]; k < off[v + 1]; ++k) t2[v] += T[eid[k]];
+    }
+
+    void enumerateTriangles(bool keepList) {
+        buildEdges();
+        const bool counts = !triReady;
+        if (counts) T.assign(m, 0);
+        for (uint32_t u = 0; u < n; ++u) {
+            for (uint32_t k = ooff[u]; k < ooff[u + 1]; ++k) mark[oadj[k]] = (int32_t)oeid[k];
+            for (uint32_t k = ooff[u]; k < ooff[u + 1]; ++k) {
+                uint32_t v = oadj[k], euv = oeid[k];
+                for (uint32_t k2 = ooff[v]; k2 < ooff[v + 1]; ++k2) {
+                    uint32_t w = oadj[k2];
+                    if (mark[w] >= 0) {
+                        uint32_t euw = (uint32_t)mark[w], evw = oeid[k2];
+                        if (keepList) tris.push_back(Tri{u, v, w, euv, euw, evw});
+                        if (counts) {
+                            ++T[euv];
+                            ++T[euw];
+                            ++T[evw];
