+    std::vector<uint32_t> vtOff, vtOpp; // per vertex: the edges opposite to it in its triangles
+
+    // per undirected edge: the sorted third vertices of its triangles
+    void buildCommonNeighbors() {
+        if (cnReady) return;
+        cnReady = true;
+        buildTriangleList();
+        cnOff.assign(m + 1, 0);
+        for (uint32_t e = 0; e < m; ++e) cnOff[e + 1] = cnOff[e] + T[e];
+        vtOff.assign(n + 1, 0);
+        for (uint32_t v = 0; v < n; ++v) vtOff[v + 1] = vtOff[v] + (uint32_t)(t2[v] / 2);
+        vtOpp.assign(vtOff[n], 0);
+        std::vector<uint32_t> vpos(vtOff.begin(), vtOff.end() - 1);
+        for (const Tri &t: tris) {
+            vtOpp[vpos[t.x]++] = t.eyz;
+            vtOpp[vpos[t.y]++] = t.exz;
+            vtOpp[vpos[t.z]++] = t.exy;
+        }
+        // appending third vertices in increasing order keeps every list sorted
+        std::vector<uint32_t> pos(cnOff.begin(), cnOff.end() - 1);
+        if (n <= 65536) {
+            cnV16.assign(cnOff[m], 0);
+            for (uint32_t x = 0; x < n; ++x)
+                for (uint32_t i = vtOff[x]; i < vtOff[x + 1]; ++i) cnV16[pos[vtOpp[i]]++] = (uint16_t)x;
+        }
+        else {
+            cnV.assign(cnOff[m], 0);
+            for (uint32_t x = 0; x < n; ++x)
+                for (uint32_t i = vtOff[x]; i < vtOff[x + 1]; ++i) cnV[pos[vtOpp[i]]++] = x;
+        }
+    }
