+    // f(a, b, c, d, e_ab, e_ac, e_ad, e_bc, e_bd, e_cd) once per 4-clique
+    template<class F>
+    void forK4(F f) {
+        buildEdges();
+        std::vector<int32_t> markU(n, -1), markV(n, -1);
+        std::vector<uint32_t> cand;
+        for (uint32_t u = 0; u < n; ++u) {
+            for (uint32_t k = ooff[u]; k < ooff[u + 1]; ++k) markU[oadj[k]] = (int32_t)oeid[k];
+            for (uint32_t k = ooff[u]; k < ooff[u + 1]; ++k) {
+                uint32_t v = oadj[k], euv = oeid[k];
+                cand.clear();
+                for (uint32_t k2 = ooff[v]; k2 < ooff[v + 1]; ++k2) {
+                    uint32_t w = oadj[k2];
+                    if (markU[w] >= 0) {
+                        cand.push_back(w);
+                        markV[w] = (int32_t)oeid[k2];
+                    }
+                }
+                for (uint32_t w: cand) {
+                    for (uint32_t k3 = ooff[w]; k3 < ooff[w + 1]; ++k3) {
+                        uint32_t x = oadj[k3];
+                        if (markV[x] >= 0)
+                            f(u, v, w, x, euv, (uint32_t)markU[w], (uint32_t)markU[x], (uint32_t)markV[w],
+                              (uint32_t)markV[x], oeid[k3]);
+                    }
+                }
+                for (uint32_t w: cand) markV[w] = -1;
+            }
+            for (uint32_t k = ooff[u]; k < ooff[u + 1]; ++k) markU[oadj[k]] = -1;
+        }
+    }
