+    bool k5Ready = false;
+    Vec k5v;                            // ordered 5-clique completions per vertex (24 per 5-clique)
+    bool k4CountReady = false;
+    Vec k4cnt;                          // 4-cliques per vertex
+    bool k4WeightedNeeded = false;
+
+    bool k4StatsNeeded() const {
+        return !prepared || k4WeightedNeeded || needed(K5MP3, 0) || needed(K5MP3, 2) || needed(K5MP3, 4);
+    }
+
+    void buildK4() { cliquePass(true, false, needed(K5, 0)); }
+
+    // One sweep over local oriented out-neighborhoods: 4-clique statistics and/or 5-cliques.
+    void cliquePass(bool wantK4, bool wantCount, bool wantK5, bool wantT = false) {
+        wantK4 = wantK4 && !k4Ready;
+        wantCount = wantCount && !wantK4 && !k4Ready && !k4CountReady;
+        wantK5 = wantK5 && !k5Ready;
+        wantT = wantT && !triReady;
+        if (!wantK4 && !wantCount && !wantK5 && !wantT) return;
+        if (wantK4) buildTriangles();
+        buildEdges();
+        const bool wantOpp = wantK4 && (!prepared || needed(K5MP3, 2));
+        if (wantT) T.assign(m, 0);
+        if (wantK4) {
+            k4Ready = true;
+            K4e.assign(m, 0);
+            k4Opp.assign(n, 0);
+        }
+        if (wantCount) {
+            k4CountReady = true;
+            k4cnt.assign(n, 0);
+        }
+        if (wantK5) {
+            k5Ready = true;
+            k5v.assign(n, 0);
+        }
+        auto add = [&](uint32_t a, uint32_t b, uint32_t c, uint32_t d, uint32_t eab, uint32_t eac, uint32_t ead,
+                       uint32_t ebc, uint32_t ebd, uint32_t ecd) {
+            ++K4e[eab];
+            ++K4e[eac];
+            ++K4e[ead];
+            ++K4e[ebc];
+            ++K4e[ebd];
+            ++K4e[ecd];
+            if (!wantOpp) return;
+            i64 tab = T[eab], tac = T[eac], tad = T[ead], tbc = T[ebc], tbd = T[ebd], tcd = T[ecd];
+            k4Opp[a] += tbc + tbd + tcd;
+            k4Opp[b] += tac + tad + tcd;
+            k4Opp[c] += tab + tad + tbd;
+            k4Opp[d] += tab + tac + tbc;
+        };
+        uint32_t maxOut = 0;
+        for (uint32_t u = 0; u < n; ++u) maxOut = std::max(maxOut, ooff[u + 1] - ooff[u]);
+        if (maxOut > 2048) {
+            if (wantT) {
+                enumerateTriangles(false);
+                wantT = false;
+            }
+            if (wantK4) forK4(add);
+            if (wantCount)
+                forK4([&](uint32_t a, uint32_t b, uint32_t c, uint32_t d, uint32_t, uint32_t, uint32_t, uint32_t,
+                          uint32_t, uint32_t) {
+                    ++k4cnt[a];
+                    ++k4cnt[b];
+                    ++k4cnt[c];
+                    ++k4cnt[d];
+                });
+            if (wantK5) countK5Global(k5v.data());
+            return;
+        }
+        // out-neighborhood of u as a local oriented graph: out/in bitsets, edge ids and triangle
+        // counts of local edges; clique statistics are accumulated locally and flushed per u
+        const size_t maxWords = ((size_t)maxOut + 63) / 64;
+        std::vector<uint64_t> lb(maxOut * maxWords + 1), lbIn(wantK5 ? maxOut * maxWords + 1 : 1), common(maxWords + 1);
+        const size_t sq = (wantK4 || wantT) ? (size_t)maxOut * maxOut + 1 : 1;
+        std::vector<uint32_t> le(sq), ce(sq);
+        std::vector<int32_t> Tl(sq), loc(n, -1);
+        std::vector<i64> Tu(maxOut + 1), cu(maxOut + 1), oppL(maxOut + 1), k5L(maxOut + 1);
+        for (uint32_t u = 0; u < n; ++u) {
+            const uint32_t D = ooff[u + 1] - ooff[u];
+            if (D < (wantT ? 2u : 3u)) continue;
+            const uint32_t *ou = oadj.data() + ooff[u], *eu = oeid.data() + ooff[u];
+            const size_t W = ((size_t)D + 63) / 64;
+            for (uint32_t i = 0; i < D; ++i) loc[ou[i]] = (int32_t)i;
+            std::fill(lb.begin(), lb.begin() + D * W, 0);
+            if (wantK5) std::fill(lbIn.begin(), lbIn.begin() + D * W, 0);
+            for (uint32_t i = 0; i < D; ++i) {
+                uint32_t v = ou[i];
+                uint64_t *bi = lb.data() + i * W;
+                for (uint32_t k2 = ooff[v]; k2 < ooff[v + 1]; ++k2) {
+                    int32_t j = loc[oadj[k2]];
+                    if (j < 0) continue;
+                    bi[j >> 6] |= 1ull << (j & 63);
+                    if (wantT) {
+                        // triangle (u, v_i, v_j)
+                        ++T[eu[i]];
+                        ++T[eu[j]];
+                        ++T[oeid[k2]];
+                    }
+                    if (wantK5) lbIn[(size_t)j * W + (i >> 6)] |= 1ull << (i & 63);
+                    if (wantK4) {
+                        size_t ij = (size_t)i * D + j;
+                        le[ij] = oeid[k2];
+                        if (wantOpp) Tl[ij] = (int32_t)T[oeid[k2]];
+                        ce[ij] = 0;
+                    }
+                }
+                if (wantK4) {
+                    if (wantOpp) Tu[i] = T[eu[i]];
+                    cu[i] = 0;
+                    oppL[i] = 0;
+                }
+                if (wantK5) k5L[i] = 0;
+                if (wantCount) cu[i] = 0;
+            }
+            i64 k5u = 0, oppU = 0, k4u = 0;
+            for (uint32_t i = 0; i < D; ++i) {
+                const uint64_t *bi = lb.data() + i * W;
+                for (size_t wj = 0; wj < W; ++wj) {
+                    uint64_t mj = bi[wj];
+                    while (mj) {
+                        uint32_t j = (uint32_t)(wj * 64 + __builtin_ctzll(mj));
+                        mj &= mj - 1;
+                        const uint64_t *bj = lb.data() + (size_t)j * W;
+                        bool any = false;
+                        for (size_t w = 0; w < W; ++w) {
+                            common[w] = bi[w] & bj[w];
+                            any = any || common[w];
+                        }
+                        if (!any) continue;
+                        const size_t ij = (size_t)i * D + j;
+                        i64 k5ij = 0, cntL = 0;
+                        for (size_t wl = 0; wl < W; ++wl) {
+                            uint64_t ml = common[wl];
+                            while (ml) {
+                                uint32_t l = (uint32_t)(wl * 64 + __builtin_ctzll(ml));
+                                ml &= ml - 1;
+                                ++cntL;
+                                if (wantCount) ++cu[l];
+                                if (wantK4) {
+                                    const size_t il = (size_t)i * D + l, jl = (size_t)j * D + l;
+                                    ++cu[l];
+                                    ++ce[il];
+                                    ++ce[jl];
+                                    if (wantOpp) {
+                                        oppU += Tl[il] + Tl[jl];
+                                        oppL[i] += Tu[l] + Tl[jl];
+                                        oppL[j] += Tu[l] + Tl[il];
+                                        oppL[l] += Tu[i] + Tu[j] + Tl[ij];
+                                    }
+                                }
+                                if (wantK5) {
+                                    const uint64_t *bo = lb.data() + (size_t)l * W, *bn = lbIn.data() + (size_t)l * W;
+                                    i64 outc = 0, inc = 0;
+                                    for (size_t w = 0; w < W; ++w) {
+                                        outc += __builtin_popcountll(common[w] & bo[w]);
+                                        inc += __builtin_popcountll(common[w] & bn[w]);
+                                    }
+                                    k5L[l] += outc + inc;
+                                    k5ij += outc;
+                                }
+                            }
+                        }
+                        if (wantK4) {
+                            cu[i] += cntL;
+                            cu[j] += cntL;
+                            ce[ij] += (uint32_t)cntL;
+                            if (wantOpp) {
+                                oppU += cntL * Tl[ij];
+                                oppL[i] += cntL * Tu[j];
+                                oppL[j] += cntL * Tu[i];
+                            }
+                        }
+                        if (wantK5) {
+                            k5L[i] += k5ij;
+                            k5L[j] += k5ij;
+                            k5u += k5ij;
+                        }
+                        if (wantCount) {
+                            cu[i] += cntL;
+                            cu[j] += cntL;
+                            k4u += cntL;
+                        }
+                    }
+                }
+            }
+            if (wantK4) {
+                // each 4-clique (u,i,j,l) contributes to the edges (u,i), (u,j), (u,l): cu counts them
+                for (uint32_t i = 0; i < D; ++i) {
+                    K4e[eu[i]] += (uint32_t)cu[i];
+                    k4Opp[ou[i]] += oppL[i];
+                    const uint64_t *bi = lb.data() + i * W;
+                    for (size_t wj = 0; wj < W; ++wj) {
+                        uint64_t mj = bi[wj];
+                        while (mj) {
+                            uint32_t j = (uint32_t)(wj * 64 + __builtin_ctzll(mj));
+                            mj &= mj - 1;
+                            K4e[le[(size_t)i * D + j]] += ce[(size_t)i * D + j];
+                        }
+                    }
+                }
+                k4Opp[u] += oppU;
+            }
+            if (wantK5) {
+                for (uint32_t i = 0; i < D; ++i) k5v[ou[i]] += 24 * k5L[i];
+                k5v[u] += 24 * k5u;
+            }
+            if (wantCount) {
+                for (uint32_t i = 0; i < D; ++i) k4cnt[ou[i]] += cu[i];
+                k4cnt[u] += k4u;
+            }
+            for (uint32_t i = 0; i < D; ++i) loc[ou[i]] = -1;
+        }
+        if (wantT) finishTriangleCounts();
+    }
