+    // ---- weighted cores ----
+
+    // root 0 of the triangle
+    void evalK3(const i64 *const *W, i64 *out) {
+        const i64 *W1 = W[1], *W2 = W[2];
+        if (W1 == ones.data() || W2 == ones.data()) {
+            // sum over b in N(v) of w(b) * T(v,b)
+            buildTriangles();
+            const i64 *w = W1 == ones.data() ? W2 : W1;
+            for (uint32_t v = 0; v < n; ++v) {
+                i64 sum = 0;
+                for (uint32_t k = off[v]; k < off[v + 1]; ++k) sum += w[adj[k]] * (i64)T[eid[k]];
+                out[v] = W[0][v] * sum;
+            }
+            return;
+        }
+        Vec s(n, 0);
+        forTriangles([&](uint32_t x, uint32_t y, uint32_t z, uint32_t, uint32_t, uint32_t) {
+            s[x] += W1[y] * W2[z] + W1[z] * W2[y];
+            s[y] += W1[x] * W2[z] + W1[z] * W2[x];
+            s[z] += W1[x] * W2[y] + W1[y] * W2[x];
+        });
+        for (uint32_t v = 0; v < n; ++v) out[v] = W[0][v] * s[v];
+    }
+
+    // root 0 of the cycle 0-1-2-3-0: W0(v) * sum_c W2(c) M1(v,c) M3(v,c)
+    void evalC4(const i64 *const *W, i64 *out) {
+        const i64 *W1 = W[1], *W2 = W[2], *W3 = W[3];
+        const i64 *one = ones.data();
+        buildA2();
+        if (a2Dense && W1 == one && W3 == one) {
+            // sum_c W2(c) A^2(v,c)^2
+            bool narrow = true;
+            for (uint32_t c = 0; c < n && narrow; ++c) narrow = W2[c] >= 0 && W2[c] < (1 << 30);
+            std::vector<int32_t> w32(narrow && W2 != one ? n : 0);
+            for (size_t c = 0; c < w32.size(); ++c) w32[c] = (int32_t)W2[c];
+            for (uint32_t v = 0; v < n; ++v) {
+                const int16_t *row = M.data() + np * v;
+                i64 sum = 0;
+                if (W2 == one) {
+                    // A^2(v,c) <= deg(c), so the sum is below the sum of squared degrees
+                    sum = dot16(row, row, np);
+                }
+                else if (narrow) {
+                    for (uint32_t c = 0; c < n; ++c) sum += (i64)w32[c] * ((int32_t)row[c] * row[c]);
+                }
+                else {
+                    for (uint32_t c = 0; c < n; ++c) sum += W2[c] * ((int32_t)row[c] * (int32_t)row[c]);
+                }
+                out[v] = W[0][v] * sum;
+            }
+            return;
+        }
+        if (a2Dense && W2 == one && (W1 == one || W3 == one)) {
+            // sum_c M_w(v,c) A^2(v,c) = sum_{x in N(v)} w(x) A^3(v,x)
+            buildHouse();
+            const i64 *Wa = W1 == one ? W3 : W1;
+            for (uint32_t v = 0; v < n; ++v) {
+                i64 sum = 0;
+                for (uint32_t k = off[v]; k < off[v + 1]; ++k) sum += Wa[adj[k]] * A3[eid[k]];
+                out[v] = W[0][v] * sum;
+            }
+            return;
+        }
+        bool same = W1 == W3;
+        Vec acc1(n, 0), acc3(same ? 0 : n, 0);
+        for (uint32_t v = 0; v < n; ++v) {
+            for (uint32_t k = off[v]; k < off[v + 1]; ++k) {
+                uint32_t x = adj[k];
+                i64 w1 = W1[x];
+                if (same) {
+                    for (uint32_t k2 = off[x]; k2 < off[x + 1]; ++k2) acc1[adj[k2]] += w1;
+                }
+                else {
+                    i64 w3 = W3[x];
+                    for (uint32_t k2 = off[x]; k2 < off[x + 1]; ++k2) {
+                        acc1[adj[k2]] += w1;
+                        acc3[adj[k2]] += w3;
+                    }
+                }
+            }
+            i64 sum = 0;
+            for (uint32_t k = off[v]; k < off[v + 1]; ++k) {
+                uint32_t x = adj[k];
+                for (uint32_t k2 = off[x]; k2 < off[x + 1]; ++k2) {
+                    uint32_t c = adj[k2];
+                    if (same) {
+                        i64 a = acc1[c];
+                        if (a) {
+                            sum += W2[c] * a * a;
+                            acc1[c] = 0;
+                        }
+                    }
+                    else if (acc1[c] | acc3[c]) {
+                        sum += W2[c] * acc1[c] * acc3[c];
+                        acc1[c] = acc3[c] = 0;
+                    }
+                }
+            }
+            out[v] = W[0][v] * sum;
+        }
+    }
