+    // 0,1: shared edge, 2,3: tips
+    Vec T64;                            // T widened, the tip sums of unweighted tips
+
+    // per undirected edge: the sum of w over the common neighbors of its endpoints
+    const Vec &tipSums(const i64 *w, Vec &store) {
+        if (w == ones.data()) {
+            if (T64.size() != m) T64.assign(T.begin(), T.end());
+            return T64;
+        }
+        store.assign(m, 0);
+        forTriangles([&](uint32_t x, uint32_t y, uint32_t z, uint32_t exy, uint32_t exz, uint32_t eyz) {
+            store[exy] += w[z];
+            store[exz] += w[y];
+            store[eyz] += w[x];
+        });
+        return store;
+    }
+
+    // 0,1: shared edge, 2,3: tips
+    void evalDiamond(const i64 *const *W, int root, i64 *out) {
+        buildTriangles();
+        const i64 *one = ones.data();
+        Vec store2, store3;
+        if (root == 0) {
+            const Vec &S2 = tipSums(W[2], store2);
+            const Vec &S3 = W[3] == W[2] ? S2 : tipSums(W[3], store3);
+            const i64 *W1 = W[1];
+            for (uint32_t v = 0; v < n; ++v) {
+                i64 sum = 0;
+                for (uint32_t k = off[v]; k < off[v + 1]; ++k) {
+                    uint32_t e = eid[k];
+                    sum += W1[adj[k]] * S2[e] * S3[e];
+                }
+                out[v] = W[0][v] * sum;
+            }
+            return;
+        }
+        const Vec &S3 = tipSums(W[3], store3);
+        const i64 *W0 = W[0], *W1 = W[1];
+        Vec acc(n, 0);
+        if (W0 == one && W1 == one) {
+            forTriangles([&](uint32_t x, uint32_t y, uint32_t z, uint32_t exy, uint32_t exz, uint32_t eyz) {
+                acc[x] += 2 * S3[eyz];
+                acc[y] += 2 * S3[exz];
+                acc[z] += 2 * S3[exy];
+            });
+        }
+        else {
+            forTriangles([&](uint32_t x, uint32_t y, uint32_t z, uint32_t exy, uint32_t exz, uint32_t eyz) {
+                acc[x] += S3[eyz] * (W0[y] * W1[z] + W0[z] * W1[y]);
+                acc[y] += S3[exz] * (W0[x] * W1[z] + W0[z] * W1[x]);
+                acc[z] += S3[exy] * (W0[x] * W1[y] + W0[y] * W1[x]);
+            });
+        }
+        for (uint32_t v = 0; v < n; ++v) out[v] = W[2][v] * acc[v];
+    }
+
+    // root 0 of the 4-clique
+    void evalK4(const i64 *const *W, i64 *out) {
+        const i64 *W1 = W[1], *W2 = W[2], *W3 = W[3];
+        const i64 *one = ones.data();
+        int weighted = (W1 != one) + (W2 != one) + (W3 != one);
+        if (weighted == 0 && !k4Ready && !k4StatsNeeded()) {
+            cliquePass(false, true, needed(K5, 0));
+            for (uint32_t v = 0; v < n; ++v) out[v] = W[0][v] * 6 * k4cnt[v];
+            return;
+        }
+        if (weighted <= 1) {
+            // ordered completions: 6 per 4-clique, or 2 * the weight of each other clique vertex
+            buildK4();
+            const i64 *w = W1 != one ? W1 : (W2 != one ? W2 : W3);
+            for (uint32_t v = 0; v < n; ++v) {
+                i64 sum = 0;
+                if (weighted == 0) {
+                    for (uint32_t k = off[v]; k < off[v + 1]; ++k) sum += K4e[eid[k]];
+                    sum *= 2;
+                }
+                else {
+                    for (uint32_t k = off[v]; k < off[v + 1]; ++k) sum += w[adj[k]] * K4e[eid[k]];
+                    sum *= 2;
+                }
+                out[v] = W[0][v] * sum;
+            }
+            return;
+        }
+        Vec s(n, 0);
+        auto per = [&](uint32_t a, uint32_t b, uint32_t c) -> i64 {
+            return W1[a] * (W2[b] * W3[c] + W2[c] * W3[b]) + W1[b] * (W2[a] * W3[c] + W2[c] * W3[a]) +
+                   W1[c] * (W2[a] * W3[b] + W2[b] * W3[a]);
+        };
+        forK4([&](uint32_t a, uint32_t b, uint32_t c, uint32_t d, uint32_t, uint32_t, uint32_t, uint32_t,
+                  uint32_t, uint32_t) {
+            s[a] += per(b, c, d);
+            s[b] += per(a, c, d);
+            s[c] += per(a, b, d);
+            s[d] += per(a, b, c);
+        });
+        for (uint32_t v = 0; v < n; ++v) out[v] = W[0][v] * s[v];
+    }
+
+    // ---- five-vertex cores ----
+
+    // closed 5-walks: sum over edges (v,x) of <A^2_v, A^2_x>
+    void evalC5(i64 *out) {
+        std::fill(out, out + n, 0);
+        buildA2();
+        if (a2Dense) {
+            for (uint32_t v = 0; v < n; ++v) {
+                const int16_t *a = M.data() + np * v;
+                for (uint32_t k = off[v]; k < off[v + 1]; ++k) {
+                    uint32_t x = adj[k];
+                    if (x < v) continue;
+                    int32_t s = dot16(a, M.data() + np * x, np);
+                    out[v] += s;
+                    out[x] += s;
+                }
+            }
+            return;
+        }
+        // general graphs: one A^2 row at a time, inner products against neighbor rows rebuilt sparsely
+        std::vector<i64> rowV(n, 0);
+        for (uint32_t v = 0; v < n; ++v) {
+            for (uint32_t k = off[v]; k < off[v + 1]; ++k) {
+                uint32_t y = adj[k];
+                for (uint32_t k2 = off[y]; k2 < off[y + 1]; ++k2) ++rowV[adj[k2]];
+            }
+            for (uint32_t k = off[v]; k < off[v + 1]; ++k) {
+                uint32_t x = adj[k];
+                if (x < v) continue;
+                i64 s = 0;
+                // <A^2_v, A^2_x> = sum_{y in N(x)} sum_{c in N(y)} A^2(v, c)
+                for (uint32_t k2 = off[x]; k2 < off[x + 1]; ++k2) {
+                    uint32_t y = adj[k2];
+                    for (uint32_t k3 = off[y]; k3 < off[y + 1]; ++k3) s += rowV[adj[k3]];
+                }
+                out[v] += s;
+                out[x] += s;
+            }
+            for (uint32_t k = off[v]; k < off[v + 1]; ++k) {
+                uint32_t y = adj[k];
+                for (uint32_t k2 = off[y]; k2 < off[y + 1]; ++k2) rowV[adj[k2]] = 0;
+            }
+        }
+    }
+
+    void evalBowtie(int root, i64 *out) {
+        buildTriangles();
+        if (root == 0) {
+            for (uint32_t v = 0; v < n; ++v) out[v] = t2[v] * t2[v];
+        }
+        else {
+            for (uint32_t v = 0; v < n; ++v) {
+                i64 s = 0;
+                for (uint32_t k = off[v]; k < off[v + 1]; ++k) s += (i64)T[eid[k]] * t2[adj[k]];
+                out[v] = s;
+            }
+        }
+    }
+
+    // A3(e): 3-walks between the endpoints of e; houseBottom: root 3 of the house
+    void buildHouse() {
+        if (a3Ready) return;
+        a3Ready = true;
+        buildTriangles();
+        A3.assign(m, 0);
+        const bool bottom = needed(HOUSE, 3);
+        if (bottom) houseBottom.assign(n, 0);
+        std::vector<int32_t> tslot(bottom ? 2ull * m : 0);
+        for (size_t k = 0; k < tslot.size(); ++k) tslot[k] = (int32_t)T[eid[k]];
+        buildA2();
+        std::vector<int32_t> row(n, 0);
+        for (uint32_t a = 0; a < n; ++a) {
+            i64 bsum = 0;
+            if (a2Dense) {
+                const int16_t *drow = M.data() + np * a;
+                uint64_t gathers = 0;
+                for (uint32_t k = off[a]; k < off[a + 1]; ++k) gathers += deg(adj[k]);
+                if (gathers * 2 > n) {
+                    // widened copy: the gathers below vectorize on 32-bit lanes
+                    for (uint32_t c = 0; c < n; ++c) row[c] = drow[c];
+                    houseRow(a, row.data(), bottom, tslot, bsum);
+                }
+                else houseRow(a, drow, bottom, tslot, bsum);
+            }
+            else {
+                for (uint32_t k = off[a]; k < off[a + 1]; ++k) {
+                    uint32_t x = adj[k];
+                    for (uint32_t k2 = off[x]; k2 < off[x + 1]; ++k2) ++row[adj[k2]];
+                }
+                houseRow(a, row.data(), bottom, tslot, bsum);
+            }
+            if (bottom) houseBottom[a] = bsum;
+            if (!a2Dense) {
+                for (uint32_t k = off[a]; k < off[a + 1]; ++k) {
+                    uint32_t x = adj[k];
+                    for (uint32_t k2 = off[x]; k2 < off[x + 1]; ++k2) row[adj[k2]] = 0;
+                }
+            }
+        }
+    }
+
+    template<class R>
+    void houseRow(uint32_t a, const R *r, bool bottom, const std::vector<int32_t> &tslot, i64 &bsum) {
+        for (uint32_t k = off[a]; k < off[a + 1]; ++k) {
+            uint32_t x = adj[k];
+            const uint32_t b = off[x], f = off[x + 1];
+            if (a < x) {
+                i64 s3 = 0;
+                for (uint32_t k2 = b; k2 < f; ++k2) s3 += r[adj[k2]];
+                A3[eid[k]] = s3;
+            }
+            if (bottom) {
+                i64 sb = 0;
+                for (uint32_t k2 = b; k2 < f; ++k2) sb += (i64)tslot[k2] * r[adj[k2]];
+                bsum += sb;
+            }
+        }
+    }
+
+    void evalHouseBottomLate(i64 *out) {
+        // root 3 requested after A3 was built without it
+        buildTriangles();
+        buildA2();
+        std::vector<int32_t> row(n, 0);
+        for (uint32_t a = 0; a < n; ++a) {
+            if (a2Dense) {
+                const int16_t *drow = M.data() + np * a;
+                for (uint32_t c = 0; c < n; ++c) row[c] = drow[c];
+            }
+            else {
+                std::fill(row.begin(), row.end(), 0);
+                for (uint32_t k = off[a]; k < off[a + 1]; ++k) {
+                    uint32_t x = adj[k];
+                    for (uint32_t k2 = off[x]; k2 < off[x + 1]; ++k2) ++row[adj[k2]];
+                }
+            }
+            i64 bsum = 0;
+            for (uint32_t k = off[a]; k < off[a + 1]; ++k) {
+                uint32_t x = adj[k];
+                for (uint32_t k2 = off[x]; k2 < off[x + 1]; ++k2) bsum += (i64)T[eid[k2]] * row[adj[k2]];
+            }
+            out[a] = bsum;
+        }
+    }
+
+    void evalHouse(int root, i64 *out) {
+        buildHouse();
+        if (root == 3) {
+            if (houseBottom.size() == n) std::copy(houseBottom.begin(), houseBottom.end(), out);
+            else evalHouseBottomLate(out);
+        }
+        else if (root == 0) {
+            for (uint32_t v = 0; v < n; ++v) {
+                i64 s = 0;
+                for (uint32_t k = off[v]; k < off[v + 1]; ++k) s += (i64)T[eid[k]] * A3[eid[k]];
+                out[v] = s;
+            }
+        }
+        else {
+            std::fill(out, out + n, 0);
+            forTriangles([&](uint32_t x, uint32_t y, uint32_t z, uint32_t exy, uint32_t exz, uint32_t eyz) {
+                out[x] += 2 * A3[eyz];
+                out[y] += 2 * A3[exz];
+                out[z] += 2 * A3[exy];
+            });
+        }
+    }
+
+    void evalGem(int root, i64 *out) {
+        buildTriangles();
+        std::fill(out, out + n, 0);
+        if (root == 0) {
+            forTriangles([&](uint32_t x, uint32_t y, uint32_t z, uint32_t exy, uint32_t exz, uint32_t eyz) {
+                i64 a = T[exy], b = T[exz], c = T[eyz];
+                out[x] += 2 * a * b;
+                out[y] += 2 * a * c;
+                out[z] += 2 * b * c;
+            });
+        }
+        else if (root == 1) {
+            forTriangles([&](uint32_t x, uint32_t y, uint32_t z, uint32_t exy, uint32_t exz, uint32_t eyz) {
+                i64 a = T[exy], b = T[exz], c = T[eyz];
+                out[x] += c * (a + b);
+                out[y] += b * (a + c);
+                out[z] += a * (b + c);
+            });
+        }
+        else {
+            Vec U(m, 0);
+            forTriangles([&](uint32_t, uint32_t, uint32_t, uint32_t exy, uint32_t exz, uint32_t eyz) {
+                i64 a = T[exy], b = T[exz], c = T[eyz];
+                U[eyz] += a + b;
+                U[exz] += a + c;
+                U[exy] += b + c;
+            });
+            forTriangles([&](uint32_t x, uint32_t y, uint32_t z, uint32_t exy, uint32_t exz, uint32_t eyz) {
+                out[x] += U[eyz];
+                out[y] += U[exz];
+                out[z] += U[exy];
+            });
+        }
+    }
+
+    // Roots of K23E. With E2(a,x) = ordered edges of G[CN(a,x)] and the diamonds (a; y,z; x),
+    // x in CN(y,z), of every triangle (a,y,z):
+    //   root 4 at v: sum_{x2,x3 in N(v)} E2(x2,x3);
+    //   root 2 at a: sum_x A^2(a,x) E2(a,x);
+    //   root 0 at v: sum_{x1 in N(v)} Q(v,x1), Q(e) = sum_{a,x in CN(e)} A^2(a,x).
+    // Each symmetric pair is visited once (x > a over the sorted common-neighbor lists).
+    // Roots already computed are skipped; a pass computes all requested roots together.
+    void buildK23(bool r0, bool r2, bool r4) {
+        r0 = r0 && !k23R0Ready;
+        r2 = r2 && !k23R2Ready;
+        r4 = r4 && !k23R4Ready;
+        if (!r0 && !r2 && !r4) return;
+        k23R0Ready = k23R0Ready || r0;
+        k23R2Ready = k23R2Ready || r2;
+        k23R4Ready = k23R4Ready || r4;
+        buildCommonNeighbors();
+        buildA2();
+        if (!cnV16.empty() || cnV.empty()) k23Pass(cnV16, r0, r2, r4);
+        else k23Pass(cnV, r0, r2, r4);
+    }
+
+    template<class IDX>
+    void k23Pass(const std::vector<IDX> &cn, bool r0, bool r2, bool r4) {
+        const bool scatter = r2 || r4, rowNeeded = r0 || r2;
+        if (r0) k23Root0.assign(n, 0);
+        if (r2) k23Root2.assign(n, 0);
+        if (r4) k23Root4.assign(n, 0);
+        Vec Q(r0 ? m : 0, 0);
+        std::vector<int32_t> e2(scatter ? n : 0, 0), arow(rowNeeded ? n : 0, 0);
+        // dense graphs read most of every row; sparse ones touch few entries
+        double diamonds = 0;
+        for (uint32_t e = 0; e < m; ++e) diamonds += (double)T[e] * T[e];
+        // a widened row copy only pays off for vectorized gathers without scatters
+        const bool denseRows = !scatter && diamonds > (double)n * n;
+        // vertices are visited in increasing order, so in each sorted list the visiting vertex
+        // sits right after the entries already visited
+        std::vector<uint32_t> cursor(m, 0);
+        std::vector<uint32_t> e2x;
+        std::vector<int32_t> e2v;
+        for (uint32_t a = 0; a < n; ++a) {
+            const uint32_t ob = vtOff[a], oe = vtOff[a + 1];
+            if (ob == oe) continue;
+            const int16_t *drow = a2Dense ? M.data() + np * a : nullptr;
+            if (rowNeeded) {
+                if (a2Dense) {
+                    if (denseRows)
+                        for (uint32_t c = a + 1; c < n; ++c) arow[c] = drow[c];
+                }
+                else {
+                    for (uint32_t k = off[a]; k < off[a + 1]; ++k) {
+                        uint32_t x = adj[k];
+                        for (uint32_t k2 = off[x]; k2 < off[x + 1]; ++k2) ++arow[adj[k2]];
+                    }
+                }
+            }
+            const i64 da = deg(a);
+            uint32_t minX = n;
+            size_t touched = 0;
+            for (uint32_t i = ob; i < oe; ++i) {
+                if (i + 4 < oe) __builtin_prefetch(cn.data() + cnOff[vtOpp[i + 4]]);
+                uint32_t e = vtOpp[i];
+                const IDX *f = cn.data() + cnOff[e + 1];
+                const IDX *L = cn.data() + cnOff[e] + (++cursor[e]);
+                const uint32_t cnt = (uint32_t)(f - L);
+                if (cnt && L[0] < minX) minX = L[0];
+                touched += cnt;
+                if (!r0) {
+                    for (uint32_t t = 0; t < cnt; ++t) e2[L[t]] += 2;
+                    continue;
+                }
+                int32_t R = 0;
+                if (a2Dense && !denseRows) {
+                    if (scatter)
+                        for (uint32_t t = 0; t < cnt; ++t) {
+                            e2[L[t]] += 2;
+                            R += drow[L[t]];
+                        }
+                    else
+                        for (uint32_t t = 0; t < cnt; ++t) R += drow[L[t]];
+                }
+                else {
+                    if (scatter)
+                        for (uint32_t t = 0; t < cnt; ++t) {
+                            e2[L[t]] += 2;
+                            R += arow[L[t]];
+                        }
+                    else
+                        for (uint32_t t = 0; t < cnt; ++t) R += arow[L[t]];
+                }
+                Q[e] += da + 2 * (i64)R;
+            }
+            if (!scatter) continue;
+            const i64 ea = t2[a];   // E2(a,a)
+            // few touched entries: revisit the lists instead of sweeping the row tail
+            const bool sweep = touched * 4 > (size_t)(n - std::min(minX, n));
+            if (r2) {
+                i64 r2sum = da * ea;
+                if (sweep) {
+                    if (a2Dense && !denseRows)
+                        for (uint32_t x = minX; x < n; ++x) {
+                            i64 val = (i64)drow[x] * e2[x];
+                            r2sum += val;
+                            k23Root2[x] += val;
+                        }
+                    else
+                        for (uint32_t x = minX; x < n; ++x) {
+                            i64 val = (i64)arow[x] * e2[x];
+                            r2sum += val;
+                            k23Root2[x] += val;
+                        }
+                }
+                else {
+                    // each touched x once: take e2[x] and clear it after use
+                    for (uint32_t i = ob; i < oe; ++i) {
+                        uint32_t e = vtOpp[i];
+                        const IDX *f = cn.data() + cnOff[e + 1];
+                        for (const IDX *L = cn.data() + cnOff[e] + cursor[e]; L < f; ++L) {
+                            uint32_t x = *L;
+                            if (!e2[x]) continue;
+                            i64 r = (a2Dense && !denseRows) ? (i64)drow[x] : (i64)arow[x];
+                            i64 val = r * e2[x];
+                            r2sum += val;
+                            k23Root2[x] += val;
+                            e2x.push_back(x);
+                            e2v.push_back(e2[x]);
+                            e2[x] = 0;
+                        }
+                    }
+                    for (size_t t = 0; t < e2x.size(); ++t) e2[e2x[t]] = e2v[t];
+                    e2x.clear();
+                    e2v.clear();
+                }
+                k23Root2[a] += r2sum;
+            }
+            if (r4) {
+                for (uint32_t k = off[a]; k < off[a + 1]; ++k) {
+                    uint32_t v = adj[k];
+                    // neighbors of v above a: a sits at slot revSlot[k] of the sorted list N(v)
+                    i64 sum = 0;
+                    for (uint32_t k2 = revSlot[k] + 1; k2 < off[v + 1]; ++k2) sum += e2[adj[k2]];
+                    k23Root4[v] += ea + 2 * sum;
+                }
+            }
+            if (sweep) {
+                if (minX < n) std::fill(e2.begin() + minX, e2.end(), 0);
+            }
+            else
+                for (uint32_t i = ob; i < oe; ++i) {
+                    uint32_t e = vtOpp[i];
+                    const IDX *f = cn.data() + cnOff[e + 1];
+                    for (const IDX *L = cn.data() + cnOff[e] + cursor[e]; L < f; ++L) e2[*L] = 0;
+                }
+            if (rowNeeded && !a2Dense) {
+                for (uint32_t k = off[a]; k < off[a + 1]; ++k) {
+                    uint32_t x = adj[k];
+                    for (uint32_t k2 = off[x]; k2 < off[x + 1]; ++k2) arow[adj[k2]] = 0;
+                }
+            }
+        }
+        if (r0)
+            for (uint32_t v = 0; v < n; ++v) {
+                i64 sum = 0;
+                for (uint32_t k = off[v]; k < off[v + 1]; ++k) sum += Q[eid[k]];
+                k23Root0[v] = sum;
+            }
+    }
+
+    void evalK23E(int root, i64 *out) {
+        buildK23(root == 0 || needed(K23E, 0), root == 2 || needed(K23E, 2), root == 4 || needed(K23E, 4));
+        const Vec &src = root == 0 ? k23Root0 : (root == 2 ? k23Root2 : k23Root4);
+        std::copy(src.begin(), src.end(), out);
+    }
+
+    void evalK5mP3(int root, i64 *out) {
+        buildTriangles();
+        std::fill(out, out + n, 0);
+        if (root == 4) {
+            buildK4();
+            forTriangles([&](uint32_t x, uint32_t y, uint32_t z, uint32_t exy, uint32_t exz, uint32_t eyz) {
+                out[x] += 4 * (i64)K4e[eyz];
+                out[y] += 4 * (i64)K4e[exz];
+                out[z] += 4 * (i64)K4e[exy];
+            });
+        }
+        else if (root == 2) {
+            buildK4();
+            for (uint32_t v = 0; v < n; ++v) out[v] = 2 * k4Opp[v];
+        }
+        else {
+            // over the 4-cliques at v, T of the three clique edges at v
+            buildK4();
+            for (uint32_t v = 0; v < n; ++v) {
+                i64 sum = 0;
+                for (uint32_t k = off[v]; k < off[v + 1]; ++k) sum += (i64)T[eid[k]] * K4e[eid[k]];
+                out[v] = 2 * sum;
+            }
+        }
+    }
+
+    // 5-cliques: common out-neighborhoods of oriented edges, extended with adjacency bitsets
+    void evalK5(i64 *out) {
+        bool k4 = needed(K4, 0) || needed(K5MP3, 0) || needed(K5MP3, 2) || needed(K5MP3, 4);
+        cliquePass(k4 && k4StatsNeeded(), k4 && !k4StatsNeeded(), true);
+        std::copy(k5v.begin(), k5v.end(), out);
+    }
+
+    void countK5Global(i64 *out) {
+        buildEdges();
+        std::fill(out, out + n, 0);
+        const size_t words = ((size_t)n + 63) / 64;
+        std::vector<uint64_t> bits(words * n, 0);
+        for (uint32_t v = 0; v < n; ++v)
+            for (uint32_t k = off[v]; k < off[v + 1]; ++k) bits[words * v + (adj[k] >> 6)] |= 1ull << (adj[k] & 63);
+        auto adjacent = [&](uint32_t a, uint32_t b) { return (bits[words * a + (b >> 6)] >> (b & 63)) & 1; };
+        std::vector<uint64_t> rank(n);
+        for (uint32_t v = 0; v < n; ++v) rank[v] = ((uint64_t)deg(v) << 32) | v;
+        std::vector<int32_t> markU(n, -1);
+        std::vector<uint32_t> c1, c2;
+        for (uint32_t u = 0; u < n; ++u) {
+            for (uint32_t k = ooff[u]; k < ooff[u + 1]; ++k) markU[oadj[k]] = 1;
+            for (uint32_t k = ooff[u]; k < ooff[u + 1]; ++k) {
+                uint32_t v = oadj[k];
+                c1.clear();
+                for (uint32_t k2 = ooff[v]; k2 < ooff[v + 1]; ++k2)
+                    if (markU[oadj[k2]] >= 0) c1.push_back(oadj[k2]);
+                if (c1.size() < 3) continue;
+                std::sort(c1.begin(), c1.end(), [&](uint32_t a, uint32_t b) { return rank[a] < rank[b]; });
+                i64 cntUV = 0;
+                for (size_t i = 0; i < c1.size(); ++i) {
+                    uint32_t w = c1[i];
+                    c2.clear();
+                    for (size_t j = i + 1; j < c1.size(); ++j)
+                        if (adjacent(w, c1[j])) c2.push_back(c1[j]);
+                    if (c2.size() < 2) continue;
+                    i64 cntW = 0;
+                    for (size_t p = 0; p < c2.size(); ++p) {
+                        uint32_t x = c2[p];
+                        i64 cntX = 0;
+                        for (size_t q2 = p + 1; q2 < c2.size(); ++q2)
+                            if (adjacent(x, c2[q2])) {
+                                out[c2[q2]] += 24;
+                                ++cntX;
+                            }
+                        out[x] += 24 * cntX;
+                        cntW += cntX;
+                    }
+                    out[w] += 24 * cntW;
+                    cntUV += cntW;
+                }
+                out[u] += 24 * cntUV;
+                out[v] += 24 * cntUV;
+            }
+            for (uint32_t k = ooff[u]; k < ooff[u + 1]; ++k) markU[oadj[k]] = -1;
+        }
+    }
+
+    void evalCore(int type, const i64 *const *W, int root, i64 *out) {
+        switch (type) {
+            case K3: evalK3(W, out); break;
+            case C4: evalC4(W, out); break;
+            case DIAMOND: evalDiamond(W, root, out); break;
+            case K4: evalK4(W, out); break;
+            case C5: evalC5(out); break;
+            case BOWTIE: evalBowtie(root, out); break;
+            case HOUSE: evalHouse(root, out); break;
+            case GEM: evalGem(root, out); break;
+            case K23E: evalK23E(root, out); break;
+            case K5MP3: evalK5mP3(root, out); break;
+            default: evalK5(out); break;
+        }
+    }
+
+    // ---- rooted homomorphism vectors ----
+    //
+    // hom(Q, r) factorizes over the branches of Q at r (r is a cut vertex). A single branch
+    // whose root is a leaf is a sparse matrix-vector product of the rest; otherwise the root
+    // lies in the 2-core, and every hanging tree contributes a vertex weight to the core kernel.
+    // Every intermediate rooted shape is cached, so equal sub-shapes of different queries are
+    // computed once per batch.
+
+    static Shape induced(const Shape &s, unsigned mask, int root) {
+        int lab[5], k = 0;
+        for (int i = 0; i < s.q; ++i) lab[i] = (mask >> i & 1) ? k++ : -1;
+        Shape t;
+        t.q = k;
+        t.root = lab[root];
+        for (int i = 0; i < s.q; ++i) {
+            if (lab[i] < 0) continue;
+            for (int j = 0; j < s.q; ++j)
+                if ((s.adj[i] >> j & 1) && lab[j] >= 0) t.adj[lab[i]] |= (uint8_t)(1u << lab[j]);
+        }
+        return t;
+    }
+
+    static unsigned componentOf(const Shape &s, unsigned allowed, int start) {
+        unsigned seen = 1u << start, frontier = seen;
+        while (frontier) {
+            unsigned next = 0;
+            for (int i = 0; i < s.q; ++i)
+                if (frontier >> i & 1) next |= s.adj[i];
+            next &= allowed & ~seen;
+            seen |= next;
+            frontier = next;
+        }
+        return seen;
+    }
+
+    // Decomposition of a shape into its cached parts. kind 0: single vertex; 1: product of
+    // branches; 2: leaf root over one sub-shape; 3: core kernel with hanging-tree weights.
+    struct Plan {
+        int kind = 0;
+        std::vector<Shape> parts;           // kind 1: branches; kind 2: one sub-shape
+        int type = 0, kroot = 0;
+        std::vector<std::pair<int, Shape>> weights;   // kernel vertex, hanging tree (rooted at its attachment)
+    };
+
+    bool plan(const Shape &s, Plan &p) {
+        if (s.q == 1) {
+            p.kind = 0;
+            return true;
+        }
+        unsigned full = (1u << s.q) - 1, rootBit = 1u << s.root;
+        unsigned rest = full & ~rootBit;
+        std::vector<unsigned> comps;
+        unsigned left = rest;
+        while (left) {
+            int start = __builtin_ctz(left);
+            unsigned c = componentOf(s, rest, start);
+            comps.push_back(c);
+            left &= ~c;
+        }
+        if (comps.size() > 1) {
+            p.kind = 1;
+            for (unsigned c: comps) p.parts.push_back(induced(s, c | rootBit, s.root));
+            return true;
+        }
+        unsigned core = twoCore(s);
+        if (!(core & rootBit)) {
+            int t = __builtin_ctz(s.adj[s.root]);
+            p.kind = 2;
+            p.parts.push_back(induced(s, rest, t));
+            return true;
+        }
+        int phi[5];
+        if (!matchCore(s, core, s.root, p.type, phi, p.kroot)) return false;
+        const CoreDef &d = coreDef(p.type);
+        p.kind = 3;
+        for (int i = 0; i < d.k; ++i) {
+            int x = phi[i];
+            unsigned hanging = s.adj[x] & ~core;
+            if (hanging && !d.weighted) return false;
+            for (int t = 0; t < s.q; ++t) {
+                if (!(hanging >> t & 1)) continue;
+                unsigned c = componentOf(s, full & ~(1u << x), t);
+                // the hanging tree rooted at x: x plus the tree behind t
+                p.weights.emplace_back(i, induced(s, c | (1u << x), x));
+            }
+        }
+        return true;
+    }
+
+    std::unordered_map<uint32_t, bool> supportCache;
+
+    bool supported(const Shape &s) {
+        uint32_t key = shapeKey(s);
+        auto it = supportCache.find(key);
+        if (it != supportCache.end()) return it->second;
+        Plan p;
+        bool ok = plan(s, p);
+        if (ok) {
+            for (const Shape &part: p.parts) ok = ok && supported(part);
+            for (const auto &w: p.weights) ok = ok && supported(w.second);
+        }
+        supportCache[key] = ok;
+        return ok;
+    }
+
+    const Vec &homCached(const Shape &s) {
+        uint32_t key = shapeKey(s);
+        auto it = shapeCache.find(key);
+        if (it != shapeCache.end()) return it->second;
+        Vec v;
+        computeHom(s, v);
+        return shapeCache.emplace(key, std::move(v)).first->second;
+    }
+
+    void computeHom(const Shape &s, Vec &res) {
+        Plan p;
+        plan(s, p);
+        if (p.kind == 0) {
+            res.assign(n, 1);
+        }
+        else if (p.kind == 1) {
+            res = homCached(p.parts[0]);
+            for (size_t i = 1; i < p.parts.size(); ++i) {
+                const Vec &h = homCached(p.parts[i]);
+                for (uint32_t v = 0; v < n; ++v) res[v] *= h[v];
+            }
+        }
+        else if (p.kind == 2) {
+            spmv(homCached(p.parts[0]), res);
+        }
+        else {
+            const CoreDef &d = coreDef(p.type);
+            // the weight of kernel vertex i is the product of hom(hanging tree, x) over its hanging trees
+            Vec weights[5];
+            bool has[5] = {false, false, false, false, false};
+            for (const auto &w: p.weights) {
+                const Vec &h = homCached(w.second);
+                if (!has[w.first]) {
+                    weights[w.first] = h;
+                    has[w.first] = true;
+                }
+                else
+                    for (uint32_t v = 0; v < n; ++v) weights[w.first][v] *= h[v];
+            }
+            const i64 *W[5];
+            for (int i = 0; i < d.k; ++i) W[i] = has[i] ? weights[i].data() : ones.data();
+            res.assign(n, 0);
+            evalCore(p.type, W, p.kroot, res.data());
+        }
+    }
+
+    // ---- queries ----
+
+    struct Term {
+        Shape s;
+        i64 coef;
+    };
+
+    static void partitions(int k, const uint8_t *padj, int orbit, std::map<uint32_t, Term> &terms) {
+        int a[5] = {0, 0, 0, 0, 0};
+        static const i64 factorial[6] = {1, 1, 2, 6, 24, 120};
+        std::function<void(int, int)> rec = [&](int i, int maxBlock) {
+            if (i == k) {
+                int blocks = maxBlock + 1;
+                int size[5] = {0, 0, 0, 0, 0};
+                for (int j = 0; j < k; ++j) ++size[a[j]];
+                i64 mu = 1;
+                for (int b = 0; b < blocks; ++b) mu *= ((size[b] - 1) % 2 ? -1 : 1) * factorial[size[b] - 1];
+                Shape s;
+                s.q = blocks;
+                s.root = a[orbit];
+                for (int u = 0; u < k; ++u)
+                    for (int v = 0; v < k; ++v)
+                        if (padj[u] >> v & 1) s.adj[a[u]] |= (uint8_t)(1u << a[v]);
+                uint32_t key = shapeKey(s);
+                auto it = terms.find(key);
+                if (it == terms.end()) terms.emplace(key, Term{s, mu});
+                else it->second.coef += mu;
+                return;
+            }
+            for (int b = 0; b <= maxBlock + 1 && b < 5; ++b) {
+                bool ok = true;
+                for (int j = 0; j < i; ++j)
+                    if (a[j] == b && (padj[i] >> j & 1)) {
+                        ok = false;
+                        break;
+                    }
+                if (!ok) continue;
+                a[i] = b;
+                rec(i + 1, std::max(maxBlock, b));
+            }
+        };
+        a[0] = 0;
+        rec(1, 0);
+    }
+
+    // Expands a query into rooted shapes with Moebius coefficients; false if unsupported.
+    bool expand(const SmallQuery &q, std::map<uint32_t, Term> &terms, i64 &divisor) {
+        if (!q.parsed || q.orbitType != 1) return false;
+        int k = q.numVertices;
+        if (k < 2 || k > 5 || q.orbit < 0 || q.orbit >= k) return false;
+        uint8_t padj[5] = {0, 0, 0, 0, 0};
+        for (const auto &e: q.edges) {
+            int a = e.first, b = e.second;
+            if (a < 0 || b < 0 || a >= k || b >= k || a == b) return false;
+            if (padj[a] >> b & 1) return false;
+            padj[a] |= (uint8_t)(1u << b);
+            padj[b] |= (uint8_t)(1u << a);
+        }
+        // connectivity
+        unsigned seen = 1, frontier = 1;
+        while (frontier) {
+            unsigned nxt = 0;
+            for (int i = 0; i < k; ++i)
+                if (frontier >> i & 1) nxt |= padj[i];
+            frontier = nxt & ~seen;
+            seen |= nxt;
+        }
+        if (seen != (1u << k) - 1) return false;
+        // automorphisms and the orbit size of the representative
+        int perm[5] = {0, 1, 2, 3, 4};
+        i64 autSize = 0;
+        unsigned orbitSet = 0;
+        do {
+            bool ok = true;
+            for (int u = 0; u < k && ok; ++u)
+                for (int v = 0; v < k; ++v)
+                    if ((padj[u] >> v & 1) && !(padj[perm[u]] >> perm[v] & 1)) {
+                        ok = false;
+                        break;
+                    }
+            if (ok) {
+                ++autSize;
+                orbitSet |= 1u << perm[q.orbit];
+            }
+        } while (std::next_permutation(perm, perm + k));
+        divisor = autSize / popc(orbitSet);
+        // every rooted homomorphism count is at most maxDeg^(k-1); keep the expansion within int64
+        if (std::pow((double)maxDeg, k - 1) * 4096.0 > 9.0e18) return false;
+        partitions(k, padj, q.orbit, terms);
+        for (auto &kv: terms)
+            if (kv.second.coef != 0 && !supported(kv.second.s)) return false;
+        return true;
+    }
+
+    void collectNeeds(const Shape &s) {
+        Plan p;
+        if (!plan(s, p)) return;
+        if (p.kind == 3 && !needed(p.type, p.kroot)) neededCores.emplace_back(p.type, p.kroot);
+        if (p.kind == 3 && p.type == K4 && !p.weights.empty()) k4WeightedNeeded = true;
+        if (p.kind == 3 && p.type == K3) {
+            unsigned verts = 0;
+            for (const auto &w: p.weights) verts |= 1u << w.first;
+            if (popc(verts) >= 2) k3PairWeighted = true;
+        }
+        for (const Shape &part: p.parts) collectNeeds(part);
+        for (const auto &w: p.weights) collectNeeds(w.second);
+    }
+
+    void prepare(const std::vector<SmallQuery> &queries) {
+        prepared = true;
+        for (const SmallQuery &q: queries) {
+            std::map<uint32_t, Term> terms;
+            i64 divisor;
+            if (!expand(q, terms, divisor)) continue;
+            for (auto &kv: terms)
+                if (kv.second.coef != 0) collectNeeds(kv.second.s);
+        }
+    }
+
+    bool count(const SmallQuery &q, std::vector<int64_t> &result) {
+        std::map<uint32_t, Term> terms;
+        i64 divisor;
+        if (!expand(q, terms, divisor)) return false;
+        Vec inj(n, 0);
+        for (auto &kv: terms) {
+            if (kv.second.coef == 0) continue;
+            const Vec &h = homCached(kv.second.s);
+            i64 c = kv.second.coef;
+            for (uint32_t v = 0; v < n; ++v) inj[v] += c * h[v];
+        }
+        result.assign(n, 0);
+        for (uint32_t v = 0; v < n; ++v) {
+            if (inj[v] < 0 || inj[v] % divisor != 0) return false;
+            result[v] = inj[v] / divisor;
+        }
+        return true;
+    }
+};
+
+SharedCounter::SharedCounter(const LocalGraph &g) : impl(new Impl(g)) {}
+
+SharedCounter::~SharedCounter() = default;
+
+bool SharedCounter::count(const SmallQuery &q, std::vector<int64_t> &result) {
+    return impl->count(q, result);
+}
+
+void SharedCounter::prepare(const std::vector<SmallQuery> &queries) {
+    impl->prepare(queries);
+}
