-// Reserved batch-aggregation interface.
+// Batch aggregation for small vertex-orbit queries.
+//
+// The local injective count of a pattern P with orbit vertex o is expanded over the
+// independent vertex partitions of P (Moebius inversion on the partition lattice):
+//     inj(P, o -> v) = sum_pi mu(pi) * hom(P / pi, [o] -> v).
+// Every rooted quotient is a connected graph with at most five vertices, so the rooted
+// homomorphism vectors are computed once per batch and shared by all queries. Trees are
+// handled by message passing; the 2-core of each quotient is evaluated by a dedicated
+// counting kernel with the hanging trees folded into vertex weights.
+
+#include <cstdint>
+#include <memory>
+#include <string>
+#include <utility>
+#include <vector>
+
+struct SmallQuery {
+    int numVertices = 0;
+    std::vector<std::pair<int, int>> edges;
+    int orbitType = -1;
+    int orbit = 0;
+    bool parsed = false;
+};
+
+bool readSmallQuery(const std::string &path, SmallQuery &q);
+
+// Undirected simple data graph in CSR form with sorted neighbor lists.
+struct LocalGraph {
+    uint32_t n = 0;
+    uint32_t m = 0;                 // number of undirected edges
+    std::vector<uint32_t> offsets;  // size n + 1
+    std::vector<uint32_t> nbrs;     // size 2m
+    bool load(const std::string &path);
+};
+
+class SharedCounter {
+public:
+    explicit SharedCounter(const LocalGraph &g);
+    ~SharedCounter();
+    // Optional: announces the batch so that fused kernels compute only the roots it needs.
+    void prepare(const std::vector<SmallQuery> &queries);
+    // Computes |SubG_{p,o}(v)| for every data vertex. Returns false if the query is outside
+    // the supported class; the caller must then use the independent path.
+    bool count(const SmallQuery &q, std::vector<int64_t> &result);
+
+private:
+    struct Impl;
+    std::unique_ptr<Impl> impl;
+};
+
+void writeLocalCounts(const std::string &path, const std::vector<int64_t> &counts);

 #endif //SCOPE_AGGREGATION_H
