+static std::vector<std::string> listQueryFiles(const std::string &path) {
+    std::vector<std::string> files;
+    DIR *dir = opendir(path.c_str());
+    if (dir != nullptr) {
+        struct dirent *ent;
+        while ((ent = readdir(dir)) != nullptr) {
+            std::string file = std::string(ent->d_name);
+            if (file[0] == '.') continue;
+            files.push_back(file);
+        }
+        closedir(dir);
+    }
+    std::sort(files.begin(), files.end(), std::greater<std::string>());
+    return files;
+}
+
+// Shared batch: every supported query is answered from rooted homomorphism vectors that are
+// computed once for the whole batch; the remaining queries use the independent path.
+static bool sharedBatch(Command &cmd) {
+    std::string queryGraphPath = cmd.getQueryGraphPath();
+    std::string resultPath = cmd.getResultPath();
+    if (resultPath.empty()) return false;
+    std::vector<std::string> files = listQueryFiles(queryGraphPath);
+    if (files.empty()) return false;
+    LocalGraph g;
+    if (!g.load(cmd.getDataGraphPath())) return false;
+    std::vector<std::string> rest;
+    {
+        std::vector<SmallQuery> queries(files.size());
+        for (size_t i = 0; i < files.size(); ++i) readSmallQuery(queryGraphPath + "/" + files[i], queries[i]);
+        SharedCounter counter(g);
+        counter.prepare(queries);
+        std::vector<int64_t> counts;
+        for (size_t i = 0; i < files.size(); ++i) {
+            if (counter.count(queries[i], counts)) writeLocalCounts(resultPath + "/" + files[i], counts);
+            else rest.push_back(files[i]);
+        }
+    }
+    if (!rest.empty()) independentMain(cmd, &rest);
+    return true;
+}
+
+int main(int argc, char **argv) {
+    Command cmd(argc, argv);
+    bool share = false;
+    for (int i = 1; i < argc; ++i)
+        if (std::string(argv[i]) == "-share") share = true;
+    if (share && cmd.getBatchQuery() && sharedBatch(cmd)) return 0;
+    return independentMain(cmd, nullptr);
+}
